    # If anything got lost (shouldn't), insert back feasibly
    unassigned = [c for c in cust_ids if c not in pos_route]
    if unassigned:
        for c in unassigned:
            best_r = None
            best_pos = None
            best_delta = None
            dc = demands[c]
            for ri in range(len(route)):
                if rload[ri] + dc > cap:
                    continue
                rt = route[ri]
                m = len(rt)
                for pos in range(m + 1):
                    if m == 0:
                        delta = d(depot, c) + d(c, depot)
                    else:
                        if pos == 0:
                            delta = d(depot, c) + d(c, rt[0]) - d(depot, rt[0])
                        elif pos == m:
                            delta = d(rt[-1], c) + d(c, depot) - d(rt[-1], depot)
                        else:
                            a = rt[pos - 1]
                            b = rt[pos]
                            delta = d(a, c) + d(c, b) - d(a, b)
                    if best_delta is None or delta < best_delta or (delta == best_delta and ri < best_r):
                        best_delta = delta
                        best_r = ri
                        best_pos = pos
            if best_r is None:
                route.append([c])
                pos_route[c] = len(route) - 1
                rload.append(dc)
            else:
                route[best_r].insert(best_pos, c)
                pos_route[c] = best_r
                rload[best_r] += dc

    # If too many routes, relocate one node from any route to any other feasible route (deterministic)
    def feasible_insertion_delta(rt, c, pos):
        m = len(rt)
        if m == 0:
            return d(depot, c) + d(c, depot)
        if pos == 0:
            return d(depot, c) + d(c, rt[0]) - d(depot, rt[0])
        if pos == m:
            return d(rt[-1], c) + d(c, depot) - d(rt[-1], depot)
        a = rt[pos - 1]
        b = rt[pos]
        return d(a, c) + d(c, b) - d(a, b)

    def try_relocate_one():
        best_move = None  # (delta_total, from_r, to_r, node, from_pos, to_pos)
        for fr in range(len(route)):
            rtA = route[fr]
            if len(rtA) <= 1:
                continue
            for i, node in enumerate(rtA):
                tr_dem = demands[node]
                for to in range(len(route)):
                    if to == fr:
                        continue
                    if rload[to] + tr_dem > cap:
                        continue
                    rtB = route[to]

                    mA = len(rtA)
                    if mA == 1:
                        delta_rem = -(d(depot, node) + d(node, depot))
                    else:
                        if i == 0:
                            nxt = rtA[1]
                            delta_rem = d(depot, nxt) - (d(depot, node) + d(node, nxt))
                        elif i == mA - 1:
                            prev = rtA[mA - 2]
                            delta_rem = d(prev, depot) - (d(prev, node) + d(node, depot))
                        else:
                            prev = rtA[i - 1]
                            nxt = rtA[i + 1]
                            delta_rem = d(prev, nxt) - (d(prev, node) + d(node, nxt))

                    mB = len(rtB)
                    best_ins = None
                    best_delta_ins = None
                    for pos in range(mB + 1):
                        delta_ins = feasible_insertion_delta(rtB, node, pos)
                        if best_delta_ins is None or delta_ins < best_delta_ins:
                            best_delta_ins = delta_ins
                            best_ins = pos

                    if best_ins is None:
                        continue
                    delta_total = delta_rem + best_delta_ins
                    if best_move is None or delta_total < best_move[0] or (
                        delta_total == best_move[0] and (fr, to, node, i, best_ins) < (best_move[1], best_move[2], best_move[3], best_move[4], best_move[5])
                    ):
                        best_move = (delta_total, fr, to, node, i, best_ins)

        if best_move is None:
            return False
        # Apply move if it reduces cost OR at least reduces number of routes by emptying a route
        delta_total, fr, to, node, i, to_pos = best_move
        routes_before = len(route)

        # Remove node from fr
        del route[fr][i]
        rload[fr] -= demands[node]
        # Update pos_route for remaining nodes in fr
        for k in route[fr]:
            pos_route[k] = fr

        # Insert into to
        route[to].insert(to_pos, node)
        pos_route[node] = to
        rload[to] += demands[node]

        # If fr became empty, delete it
        if len(route[fr]) == 0:
            del route[fr]
            del rload[fr]
            # fix pos_route indices
            for c in cust_ids:
                pr = pos_route.get(c, None)
                if pr is not None and pr > fr:
                    pos_route[c] = pr - 1

        routes_after = len(route)
        return routes_after < routes_before or delta_total < 0

    # Only limited relocation iterations to keep edits small
    iters = 0
    max_iters = max(1, 2 * len(cust_ids) // 50)
    while iters < max_iters and len(route) > veh_hint + 2:
        moved = try_relocate_one()
        iters += 1
        if not moved:
            break

    # Final feasibility enforcement: if any route violates capacity, split deterministically
    # (rare but safety)
    new_routes = []
    for rt in route:
        if not rt:
            continue
        cur = []
        cur_load = 0
        for node in rt:
            nd = demands[node]
            if cur and cur_load + nd > cap:
                new_routes.append(cur)
                cur = [node]
                cur_load = nd
            else:
                cur.append(node)
                cur_load += nd
        if cur:
            new_routes.append(cur)
    route = new_routes

    # Return full solution as list of customer-node lists (no depot)
    return [rt[:] for rt in route]
